var t=`0800-pap-and-wors`;var n=`world-0800`;var a=`ZA`;var r=`southern-africa`;var o=4;var s=68;var l={en:`Pap and Wors`,ua:`Пап із ковбасками`};var u={en:`Pap and Wors is a South Africa classic prepared with cornmeal, bratwurst, yellow onion, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Grilled bratwurst stands in for South African boerewors, not available in the catalog.`,ua:`Пап із ковбасками, страва кухні країни Південно-Африканська Республіка зі складниками: кукурудзяна крупа дрібного помелу, братвурст, жовта цибуля, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Замість південноафриканського буреворсу, якого немає в каталозі, подають братвурст на грилі.`};var g=[{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`water`,960,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 21 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 21 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:21,i:[[`cornmeal`,390,`g`]]},{en:`Grill over medium-high heat for about 22 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 22 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:22,i:[[`bratwurst`,650,`g`],[`sunflower-oil`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`tomato`,330,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var d={slug:t,id:n,country:`ZA`,region:r,servings:4,minutes:68,title:l,text:u,steps:g};export{a as country,d as default,n as id,s as minutes,r as region,o as servings,t as slug,g as steps,u as text,l as title};